const http = require("http");
const fs = require("fs");
const path = require("path");
const crypto = require("crypto");

const root = path.join(__dirname, "public");
const types = { ".html": "text/html; charset=utf-8", ".css": "text/css; charset=utf-8", ".js": "text/javascript; charset=utf-8", ".svg": "image/svg+xml" };
const newsTopicsQuery = '(AEAT OR IVA OR IRPF OR "Impuesto sobre Sociedades" OR "cuentas anuales" OR ICAC OR "normativa fiscal" OR Verifactu OR autónomos OR pymes OR "Seguridad Social" OR subvenciones)';
const newsSourceGroups = [
  ["eleconomista.es", "expansion.com", "cincodias.elpais.com", "autonomosyemprendedor.es"],
  ["iberley.es", "noticias.juridicas.com", "legaltoday.com", "confilegal.com"],
  ["economistjurist.es", "elderecho.com", "diariojuridico.com", "fiscal-impuestos.com"],
  ["economistas.es", "aedaf.es", "agenciatributaria.gob.es", "boe.es"],
  ["juntadeandalucia.es", "andaluciatrade.es"]
];
let newsCache = { expires: 0, articles: [] };

function decodeXml(value = "") {
  return value.replace(/<!\[CDATA\[([\s\S]*?)\]\]>/g, "$1").replace(/<[^>]+>/g, "").replace(/&amp;/g, "&").replace(/&quot;/g, '"').replace(/&#39;|&apos;/g, "'").replace(/&lt;/g, "<").replace(/&gt;/g, ">").trim();
}
function xmlTag(item, tag) {
  const match = item.match(new RegExp(`<${tag}(?:\\s[^>]*)?>([\\s\\S]*?)<\\/${tag}>`, "i"));
  return decodeXml(match?.[1] || "");
}
function newsTopic(title) {
  if(/ICAC|cuentas? anuales?|contabilidad|contable/i.test(title)) return "Contabilidad e ICAC";
  if(/IRPF|renta/i.test(title)) return "IRPF";
  if(/IVA/i.test(title)) return "IVA";
  if(/AEAT|Hacienda|Agencia Tributaria/i.test(title)) return "AEAT";
  return "Normativa fiscal";
}
function googleNewsArticleId(url) {
  try {
    const parsed = new URL(url);
    const match = parsed.pathname.match(/\/(?:rss\/)?articles\/([^/?]+)/i);
    return match?.[1] || "";
  } catch { return ""; }
}
function tagAttribute(tag, name) {
  const escaped = name.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
  return decodeXml(tag.match(new RegExp(`${escaped}=["']([^"']+)["']`, "i"))?.[1] || "");
}
async function originalArticleUrl(url) {
  const articleId = googleNewsArticleId(url);
  if (!articleId) return url;
  try {
    const page = await fetch(url, { headers: { "User-Agent": "Mozilla/5.0 APP-AM/1.0" }, signal: AbortSignal.timeout(6000) });
    const html = await page.text();
    const escapedId = articleId.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
    const tag = html.match(new RegExp(`<[^>]+data-n-a-id=["']${escapedId}["'][^>]*>`, "i"))?.[0] || "";
    const signature = tagAttribute(tag, "data-n-a-sg");
    const timestamp = Number(tagAttribute(tag, "data-n-a-ts"));
    if (!signature || !timestamp) return url;
    const request = ["garturlreq", [["X", "X", ["X", "X"], null, null, 1, 1, "ES:es", null, 1, null, null, null, null, null, 0, 1], "X", "X", 1, [1, 1, 1], 1, 1, null, 0, 0, null, 0], articleId, timestamp, signature];
    const body = new URLSearchParams({ "f.req": JSON.stringify([[["Fbv4je", JSON.stringify(request)]]]) }).toString();
    const response = await fetch("https://news.google.com/_/DotsSplashUi/data/batchexecute", {
      method: "POST",
      headers: { "Content-Type": "application/x-www-form-urlencoded;charset=UTF-8", "User-Agent": "Mozilla/5.0 APP-AM/1.0" },
      body,
      signal: AbortSignal.timeout(6000)
    });
    const raw = await response.text();
    const jsonStart = raw.indexOf("[[");
    if (jsonStart < 0) return url;
    const result = JSON.parse(JSON.parse(raw.slice(jsonStart))[0][2]);
    return /^https?:\/\//i.test(result?.[1]) ? result[1] : url;
  } catch { return url; }
}
async function articleMetadata(url) {
  const link = await originalArticleUrl(url);
  try {
    const response = await fetch(link, { redirect: "follow", headers: { "User-Agent": "Mozilla/5.0 APP-AM/1.0" }, signal: AbortSignal.timeout(6000) });
    const html = await response.text();
    const first = html.match(/<meta[^>]+(?:property|name)=["']og:image["'][^>]+content=["']([^"']+)/i);
    const second = html.match(/<meta[^>]+content=["']([^"']+)["'][^>]+(?:property|name)=["']og:image["']/i);
    const image = decodeXml(first?.[1] || second?.[1] || "");
    const isGooglePlaceholder = /(?:news\.google|googleusercontent|gstatic|google\.com)/i.test(image);
    return { link, image: /^https?:\/\//i.test(image) && !isGooglePlaceholder ? image : "" };
  } catch { return { link, image: "" }; }
}
async function fetchNewsFeed(domains) {
  const sources = domains.map(domain => `site:${domain}`).join(" OR ");
  const query = `${newsTopicsQuery} (${sources})`;
  const url = `https://news.google.com/rss/search?q=${encodeURIComponent(query)}&hl=es&gl=ES&ceid=ES:es`;
  const response = await fetch(url, { headers: { "User-Agent": "Mozilla/5.0 APP-AM/1.0" }, signal: AbortSignal.timeout(20000) });
  if (!response.ok) throw new Error("News source unavailable");
  const xml = await response.text();
  return [...xml.matchAll(/<item>([\s\S]*?)<\/item>/gi)].map(match => {
    const item = match[1], title = xmlTag(item, "title"), source = xmlTag(item, "source");
    const escapedSource = source.replace(/[.*+?^${}()|[\]\\]/g, "\\$&");
    return { title: title.replace(new RegExp(`\\s+-\\s+${escapedSource}$`, "i"), ""), link: xmlTag(item, "link"), source, date: xmlTag(item, "pubDate"), topic: newsTopic(title) };
  }).filter(article => article.title && article.link);
}
async function getNews(force = false) {
  if (!force && newsCache.expires > Date.now()) return newsCache.articles;
  const results = await Promise.allSettled(newsSourceGroups.map(fetchNewsFeed));
  const combined = results.flatMap(result => result.status === "fulfilled" ? result.value : []);
  if (!combined.length) throw new Error("News unavailable");
  const seen = new Set();
  const articles = combined.sort((a,b) => new Date(b.date) - new Date(a.date)).filter(article => {
    const key = article.title.toLocaleLowerCase("es").replace(/\s+/g, " ").trim();
    if (seen.has(key)) return false;
    seen.add(key);return true;
  }).slice(0, 18);
  const enriched = await Promise.all(articles.map(async article => ({ ...article, ...await articleMetadata(article.link) })));
  newsCache = { expires: Date.now() + 30 * 60 * 1000, articles: enriched };
  return enriched;
}

function passwordMatches(candidate) {
  const expected = process.env.RECORDS_PASSWORD || "1234";
  if (typeof candidate !== "string") return false;
  const left = Buffer.from(candidate), right = Buffer.from(expected);
  return left.length === right.length && crypto.timingSafeEqual(left, right);
}

function readJson(req, limit = 4096) {
  return new Promise((resolve, reject) => {
    let body = "";
    req.on("data", chunk => { body += chunk;if (body.length > limit) reject(new Error("Payload too large")); });
    req.on("end", () => { try { resolve(JSON.parse(body || "{}")); } catch (error) { reject(error); } });
    req.on("error", reject);
  });
}

const team = [
  { id: "manuel", name: "Manuel Molinero", role: "admin" },
  { id: "alvaro", name: "Álvaro Molinero", role: "admin" },
  { id: "francisco", name: "Francisco Molinero", role: "user" },
  { id: "araceli", name: "Araceli Frías", role: "user" },
  { id: "jesus", name: "Jesús Carratalá", role: "user" }
];
const dataDirectory = process.env.DATA_DIR || (fs.existsSync("/data") ? "/data" : path.join(__dirname, ".data"));
const usersFile = path.join(dataDirectory, "users.json");
const sessions = new Map();

function loadUsers() {
  try {
    const saved = JSON.parse(fs.readFileSync(usersFile, "utf8"));
    return team.map(member => ({ ...member, ...(saved.find(user => user.id === member.id) || {}) }));
  } catch { return team.map(member => ({ ...member, salt: "", passwordHash: "" })); }
}
function saveUsers(users) {
  fs.mkdirSync(dataDirectory, { recursive: true });
  const temporary = `${usersFile}.tmp`;
  fs.writeFileSync(temporary, JSON.stringify(users, null, 2), { mode: 0o600 });
  fs.renameSync(temporary, usersFile);
}
function hashPassword(password, salt = crypto.randomBytes(16).toString("hex")) {
  return { salt, passwordHash: crypto.scryptSync(password, salt, 64).toString("hex") };
}
function secureEqual(left, right) {
  const a = Buffer.from(left || "", "hex"), b = Buffer.from(right || "", "hex");
  return a.length === b.length && a.length > 0 && crypto.timingSafeEqual(a, b);
}
function cookieValue(req, name) {
  const item = (req.headers.cookie || "").split(";").map(value => value.trim()).find(value => value.startsWith(`${name}=`));
  return item ? decodeURIComponent(item.slice(name.length + 1)) : "";
}
function currentUser(req) {
  const session = sessions.get(cookieValue(req, "app_am_session"));
  if (!session || session.expires < Date.now()) return null;
  return loadUsers().find(user => user.id === session.userId) || null;
}
function publicUser(user) { return { id: user.id, name: user.name, role: user.role, passwordSet: Boolean(user.passwordHash) }; }
function json(res, status, body, headers = {}) {
  res.writeHead(status, { "Content-Type": "application/json; charset=utf-8", "Cache-Control": "no-store", ...headers });
  res.end(JSON.stringify(body));
}
function validPassword(password) { return typeof password === "string" && password.length >= 6 && password.length <= 128; }

const appIcon = Buffer.from("", "base64");

http.createServer((req, res) => {
  const requestPath = req.url.split("?")[0];
  if (requestPath === "/api/auth/status" && req.method === "GET") {
    const user = currentUser(req), users = loadUsers();
    return json(res, 200, { user: user ? publicUser(user) : null, needsSetup: !users.some(item => item.passwordHash), users: users.map(publicUser) });
  }
  if (requestPath === "/api/auth/setup" && req.method === "POST") {
    return readJson(req).then(({ userId, password, setupPassword }) => {
      const users = loadUsers();
      if (users.some(item => item.passwordHash)) return json(res, 409, { error: "La configuración inicial ya está completada." });
      const expected = process.env.ADMIN_SETUP_PASSWORD || process.env.RECORDS_PASSWORD;
      if (!expected) return json(res, 503, { error: "Falta configurar la clave privada de alta en Railway." });
      const supplied = Buffer.from(String(setupPassword || "")), target = Buffer.from(expected);
      if (supplied.length !== target.length || !crypto.timingSafeEqual(supplied, target)) return json(res, 401, { error: "La clave de configuración no es correcta." });
      const user = users.find(item => item.id === userId && item.role === "admin");
      if (!user) return json(res, 400, { error: "Seleccione a Manuel o Álvaro." });
      if (!validPassword(password)) return json(res, 400, { error: "La contraseña debe tener entre 6 y 128 caracteres." });
      Object.assign(user, hashPassword(password));saveUsers(users);
      const token = crypto.randomBytes(32).toString("hex");sessions.set(token, { userId: user.id, expires: Date.now() + 12 * 60 * 60 * 1000 });
      return json(res, 200, { user: publicUser(user) }, { "Set-Cookie": `app_am_session=${token}; HttpOnly; Secure; SameSite=Strict; Path=/; Max-Age=43200` });
    }).catch(() => json(res, 400, { error: "No se pudo completar la configuración." }));
  }
  if (requestPath === "/api/auth/login" && req.method === "POST") {
    return readJson(req).then(({ userId, password }) => {
      const user = loadUsers().find(item => item.id === userId);
      if (!user?.passwordHash || !validPassword(password)) return json(res, 401, { error: "Usuario o contraseña incorrectos." });
      const candidate = crypto.scryptSync(password, user.salt, 64).toString("hex");
      if (!secureEqual(candidate, user.passwordHash)) return json(res, 401, { error: "Usuario o contraseña incorrectos." });
      const token = crypto.randomBytes(32).toString("hex");sessions.set(token, { userId: user.id, expires: Date.now() + 12 * 60 * 60 * 1000 });
      return json(res, 200, { user: publicUser(user) }, { "Set-Cookie": `app_am_session=${token}; HttpOnly; Secure; SameSite=Strict; Path=/; Max-Age=43200` });
    }).catch(() => json(res, 400, { error: "No se pudo iniciar sesión." }));
  }
  if (requestPath === "/api/auth/logout" && req.method === "POST") {
    sessions.delete(cookieValue(req, "app_am_session"));
    return json(res, 200, { ok: true }, { "Set-Cookie": "app_am_session=; HttpOnly; Secure; SameSite=Strict; Path=/; Max-Age=0" });
  }
  if (requestPath === "/api/users" && req.method === "GET") {
    const user = currentUser(req);
    return user?.role === "admin" ? json(res, 200, loadUsers().map(publicUser)) : json(res, 403, { error: "Acceso reservado a administradores." });
  }
  if (requestPath.startsWith("/api/users/") && req.method === "PUT") {
    const admin = currentUser(req);
    if (admin?.role !== "admin") return json(res, 403, { error: "Acceso reservado a administradores." });
    const userId = decodeURIComponent(requestPath.slice("/api/users/".length));
    return readJson(req).then(({ password }) => {
      if (!validPassword(password)) return json(res, 400, { error: "La contraseña debe tener entre 6 y 128 caracteres." });
      const users = loadUsers(), user = users.find(item => item.id === userId);
      if (!user) return json(res, 404, { error: "Usuario no encontrado." });
      Object.assign(user, hashPassword(password));saveUsers(users);
      for (const [token, session] of sessions) if (session.userId === user.id && user.id !== admin.id) sessions.delete(token);
      return json(res, 200, publicUser(user));
    }).catch(() => json(res, 400, { error: "No se pudo guardar la contraseña." }));
  }
  if (req.url.split("?")[0] === "/api/verify-record-password" && req.method === "POST") {
    return readJson(req).then(({password}) => {
      const valid = passwordMatches(password);
      res.writeHead(valid ? 204 : 401, valid ? {} : { "Content-Type": "application/json; charset=utf-8" });
      res.end(valid ? undefined : JSON.stringify({ error: "La contraseña no es correcta." }));
    }).catch(() => {
      res.writeHead(400, { "Content-Type": "application/json; charset=utf-8" });
      res.end(JSON.stringify({ error: "No se pudo comprobar la contraseña." }));
    });
  }
  if (req.url.split("?")[0] === "/api/news") {
    const force = new URL(req.url, "http://localhost").searchParams.has("refresh");
    return getNews(force).then(articles => {
      res.writeHead(200, { "Content-Type": "application/json; charset=utf-8", "Cache-Control": "no-store" });
      res.end(JSON.stringify(articles));
    }).catch(() => {
      res.writeHead(503, { "Content-Type": "application/json; charset=utf-8" });
      res.end(JSON.stringify([]));
    });
  }
  if (req.url.split("?")[0] === "/app-icon.png") {
    res.writeHead(200, { "Content-Type": "image/png", "Cache-Control": "public, max-age=3600" });
    return res.end(appIcon);
  }
  const pathname = req.url === "/" ? "/index.html" : req.url.split("?")[0];
  const file = path.join(root, pathname);
  if (!file.startsWith(root)) return res.writeHead(403).end("Forbidden");
  fs.readFile(file, (error, data) => {
    if (error) return res.writeHead(404).end("Not found");
    res.writeHead(200, { "Content-Type": types[path.extname(file)] || "application/octet-stream" });
    res.end(data);
  });
}).listen(process.env.PORT || 3000);
